import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { useAccount, useReadContract, useWriteContract, useWaitForTransactionReceipt } from 'wagmi';
import { formatEther, parseEther } from 'viem';

const StakingContainer = styled.div`
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 20px;
`;

const Title = styled.h2`
  font-size: 2rem;
  margin-bottom: 2rem;
  color: #4ECDC4;
`;

const StatsContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  margin-bottom: 2rem;
`;

const StatCard = styled.div`
  background: rgba(255, 255, 255, 0.05);
  padding: 1.5rem;
  border-radius: 8px;
  text-align: center;
`;

const StatValue = styled.div`
  font-size: 2rem;
  color: #4ECDC4;
  margin-bottom: 0.5rem;
`;

const StatLabel = styled.div`
  color: #888;
`;

const StakingForm = styled.div`
  background: rgba(255, 255, 255, 0.05);
  padding: 2rem;
  border-radius: 8px;
  margin-bottom: 2rem;
`;

const InputGroup = styled.div`
  margin-bottom: 1.5rem;
`;

const Label = styled.label`
  display: block;
  margin-bottom: 0.5rem;
  color: #fff;
`;

const Input = styled.input`
  width: 100%;
  padding: 1rem;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 8px;
  color: #fff;
  font-size: 1rem;

  &:focus {
    outline: none;
    border-color: #4ECDC4;
  }
`;

const ButtonGroup = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
`;

const Button = styled.button`
  padding: 1rem;
  background: ${props => props.primary ? 'linear-gradient(90deg, #FF6B6B 0%, #4ECDC4 100%)' : 'rgba(255, 255, 255, 0.1)'};
  border: none;
  border-radius: 8px;
  color: white;
  font-size: 1.1rem;
  cursor: pointer;
  transition: transform 0.2s;

  &:hover {
    transform: scale(1.02);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
`;

const stakingContractAddress = 'YOUR_STAKING_CONTRACT_ADDRESS';
const tokenContractAddress = 'YOUR_TOKEN_CONTRACT_ADDRESS'; // Assuming you have a token contract for approval

// Placeholder ABIs - You need to replace these with your actual contract ABIs
const stakingContractAbi = [
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "account",
        "type": "address"
      }
    ],
    "name": "getStakedAmount",
    "outputs": [
      {
        "internalType": "uint256",
        "name": "",
        "type": "uint256"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  },
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "account",
        "type": "address"
      }
    ],
    "name": "getPendingRewards",
    "outputs": [
      {
        "internalType": "uint256",
        "name": "",
        "type": "uint256"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  },
  {
    "inputs": [
      {
        "internalType": "uint256",
        "name": "amount",
        "type": "uint256"
      }
    ],
    "name": "stake",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  },
  {
    "inputs": [],
    "name": "unstake",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  },
  {
    "inputs": [],
    "name": "claimRewards",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  }
];

const tokenContractAbi = [
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "spender",
        "type": "address"
      },
      {
        "internalType": "uint256",
        "name": "amount",
        "type": "uint256"
      }
    ],
    "name": "approve",
    "outputs": [
      {
        "internalType": "bool",
        "name": "",
        "type": "bool"
      }
    ],
    "stateMutability": "nonpayable",
    "type": "function"
  },
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "owner",
        "type": "address"
      },
      {
        "internalType": "address",
        "name": "spender",
        "type": "address"
      }
    ],
    "name": "allowance",
    "outputs": [
      {
        "internalType": "uint256",
        "name": "",
        "type": "uint256"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  }
];

const Staking = () => {
  const { address: account } = useAccount();
  const [stakedAmount, setStakedAmount] = useState('0');
  const [rewards, setRewards] = useState('0');
  const [stakeAmount, setStakeAmount] = useState('');
  const [loading, setLoading] = useState(false);

  // Read contract data
  const { data: stakedAmountData } = useReadContract({
    abi: stakingContractAbi,
    address: stakingContractAddress,
    functionName: 'getStakedAmount',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  const { data: rewardsData } = useReadContract({
    abi: stakingContractAbi,
    address: stakingContractAddress,
    functionName: 'getPendingRewards',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  // Write contract data for staking
  const { writeContract: writeStake, data: stakeHash, isPending: isStakePending, isError: isStakeError, error: stakeErrorWrite } = useWriteContract();
  const { isLoading: isStakeConfirming, isSuccess: isStakeConfirmed, error: stakeErrorConfirm } = useWaitForTransactionReceipt({
    hash: stakeHash,
  });
      
  // Write contract data for unstaking
  const { writeContract: writeUnstake, data: unstakeHash, isPending: isUnstakePending, isError: isUnstakeError, error: unstakeErrorWrite } = useWriteContract();
  const { isLoading: isUnstakeConfirming, isSuccess: isUnstakeConfirmed, error: unstakeErrorConfirm } = useWaitForTransactionReceipt({
    hash: unstakeHash,
  });

  // Write contract data for claiming rewards
  const { writeContract: writeClaim, data: claimHash, isPending: isClaimPending, isError: isClaimError, error: claimErrorWrite } = useWriteContract();
  const { isLoading: isClaimConfirming, isSuccess: isClaimConfirmed, error: claimErrorConfirm } = useWaitForTransactionReceipt({
    hash: claimHash,
  });

  // Approval for staking
  const { writeContract: writeApprove, data: approveHash, isPending: isApprovePending, isError: isApproveError, error: approveErrorWrite } = useWriteContract();
  const { isLoading: isApproveConfirming, isSuccess: isApproveConfirmed, error: approveErrorConfirm } = useWaitForTransactionReceipt({
    hash: approveHash,
  });

  const { data: allowanceData } = useReadContract({
    abi: tokenContractAbi,
    address: tokenContractAddress,
    functionName: 'allowance',
    args: [account, stakingContractAddress],
    query: {
      enabled: !!account,
    },
  });

  useEffect(() => {
    if (stakedAmountData !== undefined) {
      setStakedAmount(formatEther(stakedAmountData));
    }
  }, [stakedAmountData]);

  useEffect(() => {
    if (rewardsData !== undefined) {
      setRewards(formatEther(rewardsData));
    }
  }, [rewardsData]);

  const handleStake = async () => {
    if (!account) {
      alert('Please connect your wallet first');
      return;
    }

    if (!stakeAmount || parseFloat(stakeAmount) <= 0) {
      alert('Please enter a valid amount');
      return;
    }

    setLoading(true);
    const amountToStake = parseEther(stakeAmount);
      
    // Check allowance first
    if (allowanceData < amountToStake) {
      writeApprove({
        abi: tokenContractAbi,
        address: tokenContractAddress,
        functionName: 'approve',
        args: [stakingContractAddress, amountToStake],
      });
    } else {
      writeStake({
        abi: stakingContractAbi,
        address: stakingContractAddress,
        functionName: 'stake',
        args: [amountToStake],
      });
    }
  };

  const handleUnstake = async () => {
    if (!account) {
      alert('Please connect your wallet first');
      return;
    }

    setLoading(true);
    writeUnstake({
      abi: stakingContractAbi,
      address: stakingContractAddress,
      functionName: 'unstake',
    });
  };

  const handleClaimRewards = async () => {
    if (!account) {
      alert('Please connect your wallet first');
      return;
    }

    setLoading(true);
    writeClaim({
      abi: stakingContractAbi,
      address: stakingContractAddress,
      functionName: 'claimRewards',
    });
  };

  // Handle approve transaction status
  useEffect(() => {
    if (isApprovePending) {
      setLoading(true);
    } else if (isApproveError) {
      console.error('Error initiating approval:', approveErrorWrite);
      alert('Error initiating approval. Please try again.');
      setLoading(false);
    } else if (approveHash) {
      // Approval transaction sent, waiting for confirmation
    }
  }, [isApprovePending, isApproveError, approveErrorWrite, approveHash]);

  useEffect(() => {
    if (isApproveConfirming) {
      // Approval confirming
    } else if (isApproveConfirmed) {
      alert('Approval successful! Now you can stake.');
      // Automatically try to stake after successful approval
      const amountToStake = parseEther(stakeAmount);
      writeStake({
        abi: stakingContractAbi,
        address: stakingContractAddress,
        functionName: 'stake',
        args: [amountToStake],
      });
    } else if (approveErrorConfirm) {
      console.error('Error confirming approval:', approveErrorConfirm);
      alert('Error confirming approval. Please try again.');
      setLoading(false);
    }
  }, [isApproveConfirming, isApproveConfirmed, approveErrorConfirm, writeStake, stakeAmount]);
      
  // Handle stake transaction status
  useEffect(() => {
    if (isStakePending) {
      setLoading(true);
    } else if (isStakeError) {
      console.error('Error initiating stake:', stakeErrorWrite);
      alert('Error initiating stake. Please try again.');
      setLoading(false);
    } else if (stakeHash) {
      // Stake transaction sent, waiting for confirmation
    }
  }, [isStakePending, isStakeError, stakeErrorWrite, stakeHash]);

  useEffect(() => {
    if (isStakeConfirming) {
      // Stake confirming
    } else if (isStakeConfirmed) {
      alert('Staked successfully!');
      setStakeAmount('');
      setLoading(false);
    } else if (stakeErrorConfirm) {
      console.error('Error confirming stake:', stakeErrorConfirm);
      alert('Error staking. Please try again.');
      setLoading(false);
    }
  }, [isStakeConfirming, isStakeConfirmed, stakeErrorConfirm]);

  // Handle unstake transaction status
  useEffect(() => {
    if (isUnstakePending) {
      setLoading(true);
    } else if (isUnstakeError) {
      console.error('Error initiating unstake:', unstakeErrorWrite);
      alert('Error initiating unstake. Please try again.');
      setLoading(false);
    } else if (unstakeHash) {
      // Unstake transaction sent, waiting for confirmation
    }
  }, [isUnstakePending, isUnstakeError, unstakeErrorWrite, unstakeHash]);

  useEffect(() => {
    if (isUnstakeConfirming) {
      // Unstake confirming
    } else if (isUnstakeConfirmed) {
      alert('Unstaked successfully!');
      setLoading(false);
    } else if (unstakeErrorConfirm) {
      console.error('Error confirming unstake:', unstakeErrorConfirm);
      alert('Error unstaking. Please try again.');
      setLoading(false);
    }
  }, [isUnstakeConfirming, isUnstakeConfirmed, unstakeErrorConfirm]);

  // Handle claim rewards transaction status
  useEffect(() => {
    if (isClaimPending) {
      setLoading(true);
    } else if (isClaimError) {
      console.error('Error initiating claim:', claimErrorWrite);
      alert('Error initiating claim. Please try again.');
      setLoading(false);
    } else if (claimHash) {
      // Claim transaction sent, waiting for confirmation
    }
  }, [isClaimPending, isClaimError, claimErrorWrite, claimHash]);

  useEffect(() => {
    if (isClaimConfirming) {
      // Claim confirming
    } else if (isClaimConfirmed) {
      alert('Rewards claimed successfully!');
      setLoading(false);
    } else if (claimErrorConfirm) {
      console.error('Error confirming claim:', claimErrorConfirm);
      alert('Error claiming rewards. Please try again.');
      setLoading(false);
    }
  }, [isClaimConfirming, isClaimConfirmed, claimErrorConfirm]);

  return (
    <StakingContainer>
      <Title>Staking</Title>

      <StatsContainer>
        <StatCard>
          <StatValue>{stakedAmount}</StatValue>
          <StatLabel>Staked Amount (PAI)</StatLabel>
        </StatCard>
        <StatCard>
          <StatValue>{rewards}</StatValue>
          <StatLabel>Pending Rewards (PAI)</StatLabel>
        </StatCard>
      </StatsContainer>

      <StakingForm>
        <InputGroup>
          <Label>Amount to Stake</Label>
          <Input
            type="number"
            value={stakeAmount}
            onChange={(e) => setStakeAmount(e.target.value)}
            placeholder="Enter amount to stake"
            min="0"
            step="0.01"
          />
        </InputGroup>

        <ButtonGroup>
          <Button
            primary
            onClick={handleStake}
            disabled={loading || !stakeAmount || !account}
          >
            {loading ? 'Processing...' : 'Stake'}
          </Button>
          <Button
            onClick={handleUnstake}
            disabled={loading || !account || parseFloat(stakedAmount) <= 0}
          >
            {loading ? 'Processing...' : 'Unstake'}
          </Button>
        </ButtonGroup>
      </StakingForm>

      <Button
        primary
        onClick={handleClaimRewards}
        disabled={loading || !account || parseFloat(rewards) <= 0}
      >
        {loading ? 'Processing...' : 'Claim Rewards'}
      </Button>
    </StakingContainer>
  );
};

export default Staking; 