import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { useAccount, useReadContract, useWriteContract, useWaitForTransactionReceipt } from 'wagmi';
import { formatEther } from 'viem';

const ReferralContainer = styled.div`
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 20px;
`;

const Title = styled.h2`
  font-size: 2rem;
  margin-bottom: 2rem;
  color: #4ECDC4;
`;

const ReferralLink = styled.div`
  background: rgba(255, 255, 255, 0.1);
  padding: 1rem;
  border-radius: 8px;
  margin-bottom: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const LinkText = styled.span`
  color: #4ECDC4;
  word-break: break-all;
`;

const CopyButton = styled.button`
  padding: 0.5rem 1rem;
  background: rgba(78, 205, 196, 0.2);
  border: none;
  border-radius: 4px;
  color: #fff;
  cursor: pointer;
  transition: all 0.3s ease;

  &:hover {
    background: rgba(78, 205, 196, 0.3);
  }
`;

const StatsContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  margin-bottom: 2rem;
`;

const StatCard = styled.div`
  background: rgba(255, 255, 255, 0.05);
  padding: 1.5rem;
  border-radius: 8px;
  text-align: center;
`;

const StatValue = styled.div`
  font-size: 2rem;
  color: #4ECDC4;
  margin-bottom: 0.5rem;
`;

const StatLabel = styled.div`
  color: #888;
`;

const ClaimButton = styled.button`
  width: 100%;
  padding: 1rem;
  background: linear-gradient(90deg, #FF6B6B 0%, #4ECDC4 100%);
  border: none;
  border-radius: 8px;
  color: white;
  font-size: 1.1rem;
  cursor: pointer;
  transition: transform 0.2s;

  &:hover {
    transform: scale(1.02);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
`;

const idoContractAddress = 'YOUR_IDO_CONTRACT_ADDRESS';
// Placeholder ABI - You need to replace this with your actual contract ABI
const idoContractAbi = [
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "account",
        "type": "address"
      }
    ],
    "name": "getReferralStats",
    "outputs": [
      {
        "components": [
          {
            "internalType": "uint256",
            "name": "totalReferrals",
            "type": "uint256"
          },
          {
            "internalType": "uint256",
            "name": "totalRewards",
            "type": "uint256"
          }
        ],
        "internalType": "struct IDO.ReferralStats",
        "name": "",
        "type": "tuple"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  },
  {
    "inputs": [],
    "name": "claimReferralRewards",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  }
];

const Referral = () => {
  const { address: account } = useAccount();
  const [referralLink, setReferralLink] = useState('');
  const [referralCount, setReferralCount] = useState(0);
  const [totalRewards, setTotalRewards] = useState('0');
  const [loading, setLoading] = useState(false);

  // Fetch referral stats
  const { data: referralStatsData } = useReadContract({
    abi: idoContractAbi,
    address: idoContractAddress,
    functionName: 'getReferralStats',
    args: [account],
    query: {
      enabled: !!account,
    },
  });
      
  // Claim rewards
  const { writeContract, data: hash, isPending: isClaimPending, isError: isClaimError, error: claimErrorWrite } = useWriteContract();
  const { isLoading: isConfirming, isSuccess: isConfirmed, error: claimErrorConfirm } = useWaitForTransactionReceipt({
    hash,
  });

  useEffect(() => {
    if (referralStatsData !== undefined) {
      setReferralCount(Number(referralStatsData.totalReferrals));
      setTotalRewards(formatEther(referralStatsData.totalRewards));
    }
  }, [referralStatsData]);

  useEffect(() => {
    if (account) {
      const baseUrl = window.location.origin;
      setReferralLink(`${baseUrl}/?ref=${account}`);
    }
  }, [account]);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(referralLink);
    alert('Referral link copied to clipboard!');
  };

  const handleClaimRewards = async () => {
    if (!account) {
      alert('Please connect your wallet first');
      return;
    }

    setLoading(true);
    writeContract({
      abi: idoContractAbi,
      address: idoContractAddress,
      functionName: 'claimReferralRewards',
    });
  };

  useEffect(() => {
    if (isClaimPending) {
      setLoading(true);
    } else if (isClaimError) {
      console.error('Error initiating claim:', claimErrorWrite);
      alert('Error initiating claim. Please try again.');
      setLoading(false);
    } else if (hash) {
      // Transaction sent, waiting for confirmation
    }
  }, [isClaimPending, isClaimError, claimErrorWrite, hash]);

  useEffect(() => {
    if (isConfirming) {
      // Transaction confirming
    } else if (isConfirmed) {
      alert('Rewards claimed successfully!');
      // No need to call fetchReferralStats explicitly, useReadContract will re-fetch automatically
      setLoading(false);
    } else if (claimErrorConfirm) {
      console.error('Error confirming transaction:', claimErrorConfirm);
      alert('Error confirming transaction. Please try again.');
      setLoading(false);
    }
  }, [isConfirming, isConfirmed, claimErrorConfirm]);

  return (
    <ReferralContainer>
      <Title>Referral Program</Title>
      
      <ReferralLink>
        <LinkText>{referralLink}</LinkText>
        <CopyButton onClick={handleCopyLink}>Copy</CopyButton>
      </ReferralLink>

      <StatsContainer>
        <StatCard>
          <StatValue>{referralCount}</StatValue>
          <StatLabel>Total Referrals</StatLabel>
        </StatCard>
        <StatCard>
          <StatValue>{totalRewards}</StatValue>
          <StatLabel>Total Rewards (PAI)</StatLabel>
        </StatCard>
      </StatsContainer>

      <ClaimButton
        onClick={handleClaimRewards}
        disabled={loading || !account || parseFloat(totalRewards) <= 0}
      >
        {loading ? 'Processing...' : 'Claim Rewards'}
      </ClaimButton>
    </ReferralContainer>
  );
};

export default Referral; 