import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { useAccount, useReadContract } from 'wagmi';
import { formatEther } from 'viem';

const DashboardContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
`;

const Title = styled.h2`
  font-size: 2rem;
  margin-bottom: 2rem;
  color: #4ECDC4;
`;

const StatsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
`;

const StatCard = styled.div`
  background: rgba(255, 255, 255, 0.05);
  padding: 1.5rem;
  border-radius: 8px;
  text-align: center;
`;

const StatValue = styled.div`
  font-size: 2rem;
  color: #4ECDC4;
  margin-bottom: 0.5rem;
`;

const StatLabel = styled.div`
  color: #888;
`;

const HistorySection = styled.div`
  background: rgba(255, 255, 255, 0.05);
  padding: 2rem;
  border-radius: 8px;
  margin-bottom: 2rem;
`;

const SectionTitle = styled.h3`
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  color: #4ECDC4;
`;

const HistoryList = styled.div`
  display: flex;
  flex-direction: column;
  gap: 1rem;
`;

const HistoryItem = styled.div`
  background: rgba(255, 255, 255, 0.05);
  padding: 1rem;
  border-radius: 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const HistoryInfo = styled.div`
  display: flex;
  flex-direction: column;
`;

const HistoryType = styled.span`
  color: #fff;
  font-weight: bold;
`;

const HistoryDate = styled.span`
  color: #888;
  font-size: 0.9rem;
`;

const HistoryAmount = styled.span`
  color: #4ECDC4;
  font-weight: bold;
`;

const tokenContractAddress = '0x8f518f33ab7b97c57dd28c4614925684bf6bc048';
const stakingContractAddress = 'YOUR_STAKING_CONTRACT_ADDRESS';
const idoContractAddress = 'YOUR_IDO_CONTRACT_ADDRESS';

// Placeholder ABIs - You need to replace these with your actual contract ABIs
const tokenContractAbi = [
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "account",
        "type": "address"
      }
    ],
    "name": "balanceOf",
    "outputs": [
      {
        "internalType": "uint256",
        "name": "",
        "type": "uint256"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  }
];

const stakingContractAbi = [
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "account",
        "type": "address"
      }
    ],
    "name": "getStakedAmount",
    "outputs": [
      {
        "internalType": "uint256",
        "name": "",
        "type": "uint256"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  },
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "account",
        "type": "address"
      }
    ],
    "name": "getPendingRewards",
    "outputs": [
      {
        "internalType": "uint256",
        "name": "",
        "type": "uint256"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  }
];

const idoContractAbi = [
  {
    "inputs": [
      {
        "internalType": "address",
        "name": "account",
        "type": "address"
      }
    ],
    "name": "getReferralStats",
    "outputs": [
      {
        "components": [
          {
            "internalType": "uint256",
            "name": "totalReferrals",
            "type": "uint256"
          },
          {
            "internalType": "uint256",
            "name": "totalRewards",
            "type": "uint256"
          }
        ],
        "internalType": "struct IDO.ReferralStats",
        "name": "",
        "type": "tuple"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  }
];

const Dashboard = () => {
  const { address: account } = useAccount();
  const [totalTokens, setTotalTokens] = useState('0');
  const [stakedTokens, setStakedTokens] = useState('0');
  const [referralRewards, setReferralRewards] = useState('0');
  const [stakingRewards, setStakingRewards] = useState('0');
  const [history, setHistory] = useState([]);

  // Fetch token balance
  const { data: totalTokensData } = useReadContract({
    abi: tokenContractAbi,
    address: tokenContractAddress,
    functionName: 'balanceOf',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  // Fetch staked amount
  const { data: stakedTokensData } = useReadContract({
    abi: stakingContractAbi,
    address: stakingContractAddress,
    functionName: 'getStakedAmount',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  // Fetch referral rewards
  const { data: referralStatsData } = useReadContract({
    abi: idoContractAbi,
    address: idoContractAddress,
    functionName: 'getReferralStats',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  // Fetch staking rewards
  const { data: stakingRewardsData } = useReadContract({
    abi: stakingContractAbi,
    address: stakingContractAddress,
    functionName: 'getPendingRewards',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  useEffect(() => {
    if (totalTokensData !== undefined) {
      setTotalTokens(formatEther(totalTokensData));
    }
  }, [totalTokensData]);

  useEffect(() => {
    if (stakedTokensData !== undefined) {
      setStakedTokens(formatEther(stakedTokensData));
    }
  }, [stakedTokensData]);

  useEffect(() => {
    if (referralStatsData !== undefined) {
      setReferralRewards(formatEther(referralStatsData.totalRewards));
    }
  }, [referralStatsData]);

  useEffect(() => {
    if (stakingRewardsData !== undefined) {
      setStakingRewards(formatEther(stakingRewardsData));
    }
  }, [stakingRewardsData]);

  useEffect(() => {
    // TODO: Implement history fetching
    // This is a mock history for now
    setHistory([
      {
        type: 'Stake',
        amount: '1000 PAI',
        date: '2024-03-15 14:30',
      },
      {
        type: 'Referral Reward',
        amount: '50 PAI',
        date: '2024-03-14 09:15',
      },
      {
        type: 'IDO Purchase',
        amount: '5000 PAI',
        date: '2024-03-13 16:45',
      },
    ]);
  }, []); // Empty dependency array means this runs once on mount
  return (
    <DashboardContainer>
      <Title>Dashboard</Title>

      <StatsGrid>
        <StatCard>
          <StatValue>{totalTokens}</StatValue>
          <StatLabel>Total PAI Tokens</StatLabel>
        </StatCard>
        <StatCard>
          <StatValue>{stakedTokens}</StatValue>
          <StatLabel>Staked Tokens</StatLabel>
        </StatCard>
        <StatCard>
          <StatValue>{referralRewards}</StatValue>
          <StatLabel>Referral Rewards</StatLabel>
        </StatCard>
        <StatCard>
          <StatValue>{stakingRewards}</StatValue>
          <StatLabel>Staking Rewards</StatLabel>
        </StatCard>
      </StatsGrid>

      <HistorySection>
        <SectionTitle>Transaction History</SectionTitle>
        <HistoryList>
          {history.map((item, index) => (
            <HistoryItem key={index}>
              <HistoryInfo>
                <HistoryType>{item.type}</HistoryType>
                <HistoryDate>{item.date}</HistoryDate>
              </HistoryInfo>
              <HistoryAmount>{item.amount}</HistoryAmount>
            </HistoryItem>
          ))}
        </HistoryList>
      </HistorySection>
    </DashboardContainer>
  );
};

export default Dashboard; 